        },
        "metadata" => %{
          "ead" => %{
            "archdesc" => %{
              "accessrestrict" => %{
                "head" => "Conditions Governing Access",
                "id" => "aspace_83b2825634ccf905ec5d093556597716",
                "p" => "Most of this collection is available on the web, linked from individual folder records in this finding aid. The original paper copies of the first nine series are located at the Caltech Archives, where access is available to anyone conducting research for which it is necessary; please contact the Caltech Archives to make an appointment. The original Director's Files of the Mount Wilson Observatory are located at the Huntington Library, where they are available to qualified researchers by application through their Reader Services Department."
              },
              "altformavail" => %{
                "head" => "Existence and Location of Copies",
                "id" => "aspace_0d751c70d12c3749f95ce16778e6d0a0",
                "p" => "In 1968, the Carnegie Institution of Washington and the California Institute of Technology used funds from the National Historical Publications Commission to publish a microfilm edition of 100 rolls that includes most of the contents of the Hale Papers. In 2018, Caltech, the Huntington Library, and the Carnegie Institution collaborated to digitize this microfilm edition, creating a web edition which is linked from individual folder records in this finding aid. Both the microfilm edition and the web edition omit portions of the collection, which are noted throughout the finding aid."
              },
              "arrangement" => %{
                "head" => "Arrangement",
                "id" => "aspace_a4b9666fe52538280767f8be87954911",
                "p" => "The heart of the Hale collection consists of the personal and organizational correspondence and the Director's Files of the Mount Wilson Observatory. All three of these groups should be used together. Since Hale's own arrangement of his files was respected in the organization of the collection, the personal correspondence contains scattered files on organizations. Furthermore, all three groups of files contain material related to individuals, organizations, and problems in science. For example, a good deal of information on the Mount Wilson Observatory is in the Robert S. Woodward file, among many others, in the personal section. Similarly, substantial material on William W. Campbell is to be found in the National Academy of Sciences files in the organizational section. Cross-checking for material on given subjects must also be done within particular sections. For instance, the files on international scientific organizations, which deal mainly with the International Research Council and its associated Unions, may be used together with the records relating to the National Academy of Sciences and the National Research Council."
              },
              "bioghist" => %{
                "head" => "Biographical / Historical",
                "id" => "aspace_59318e72ab8586ae6597587d963e76d8",
                "p" => "George Ellery Hale was born in Chicago in 1868. After receiving his B.S. from MIT in 1890, he quickly established a scientific reputation for his invention of the spectroheliograph, then made important contributions to the study of solar phenomena, organized and coedited the Astrophysical Journal, and led the design, funding and construction of the Kenwood, Yerkes, Mount Wilson and Palomar Observatories. In 1904, Hale became director of the Mount Wilson Observatory and settled in Pasadena, California, where became deeply involved in local education and culture, including the creation of Caltech and the Huntington Library. Meanwhile, he revivified the National Academy of Sciences by organizing the National Research Council, obtaining a substantial endowment, and establishing the National Research Council Fellowships. Before World War I, Hale was a founder of the International Union of Cooperation in Solar Research, Foreign Secretary of the National Academy of Sciences, and frequent delegate to the International Association of Academies. After the war, he was instrumental in the establishment of the International Research Council and served as president of its successor, the International Council of Scientific Unions, from 1931 to 1934. Hale died in 1938."
              },
              "controlaccess" => %{
                "occupation" => %{
                  "authfilenumber" => "http://id.loc.gov/authorities/subjects/sh85009031",
                  "content" => "Astrophysicists",
                  "source" => "lcsh"
                },
                "subject" => [
                  %{
                    "authfilenumber" => "http://id.loc.gov/authorities/subjects/sh85008999",
                    "content" => "Astronomical observatories",
                    "source" => "lcsh"
                  },
                  %{
                    "authfilenumber" => "http://id.loc.gov/authorities/subjects/sh85126413",
                    "content" => "Spectrohelioscope",
                    "source" => "lcsh"
                  },
                  %{
                    "authfilenumber" => "http://id.loc.gov/authorities/subjects/sh85009032",
                    "content" => "Astrophysics",
                    "source" => "lcsh"
                  }
                ]
              },
              "custodhist" => %{
                "head" => "Custodial History",
                "id" => "aspace_df6a78f4350bb60d94c15392872c46ec",
                "p" => ["At the time of Hale's death his papers were located at the headquarters of the Mount Wilson Obervatory. Within a few years his secretary, Louise F. Gianetti, separated the papers that she judged to be part of his personal collection from those that pertained to the affairs of the Observatory. These personal papers, filling some 28 file drawers, were moved to the attic of Hale's own solar laboratory on Holladay Road in Pasadena. The Observatory papers, occupying some 9 file drawers, remained at the Mount Wilson headquarters.",
                 "Hale's personal papers were placed in the custody of the California Institute of Technology by his heirs in 1966. At that time, a new administrative building for the Mount Wilson Observatory was planned, and the Hale papers were to be brought together into one unified collection and housed within that structure. This building was never built. Further, the agreement between the California Institute of Technology and the Carnegie Institution of Washington for the joint operation of the Mount Wilson and Palomar Observatories, established in 1948, was dissolved in 1980. A few years later, the Carnegie Institution turned over its Hale manuscripts, the so-called Director's Files, to the Huntington Library, along with other materials relating to the Mount Wilson Observatory, including a rare book collection. The remainder of the Hale papers—by far the bulk of the manuscript material—remained in the custody of Caltech. According to Evelina Hale's original stipulation, they were to do so until the completion of the new building which would house the collection—a project which was ultimately never completed. Thus the Hale papers are divided between two neighboring institutions, and each administers its portion."]
              },
              "did" => %{
                "abstract" => %{
                  "content" => [": this collection is available on the web. George Ellery Hale (1868–1938) was an influential astrophysicist and science administrator. This collection of Hale's scientific, professional, and personal papers documents his roles in inventing the spectrohelioscope; promoting international cooperation among scientists; and founding major observatories, as well as the California Institute of Technology, Huntington Library,",
                   ", and National Research Council."],
