                    "id" => "aspace_a5c6080e1ce58cc34ec985e761edcd36",
                    "level" => "series",
                    "scopecontent" => %{
                      "head" => "Scope and Contents",
                      "id" => "aspace_3f82970bca51113dfd03f0d61a2a08dc",
                      "p" => "The documents relating to Hale's scientific work are of two types, notebooks and letters. There are twelve notebooks. Three appear to be for 1892, 1893, and 1909 respectively; the rest are dated 1905, 1906, 1911, 1916, 1917, 1920-1930, 1924, 1933, and 1934. In addition to strictly scientific work, Hale recorded in these notebooks ideas and plans for institutions with which he was associated, drafts of articles, and, on occasion, his general thoughts. The letters, all of which date between 1926 and 1936, deal with Hale's work on the spectrohelioscope."
                    }
                  },
                  %{
                    "altformavail" => %{
                      "head" => "Existence and Location of Copies",
                      "id" => "aspace_4b3e9802a3c2dddd2a64fb76216fbdf3",
                      "p" => "Two boxes of correspondence concerning Hale's business affairs and eight boxes of bills and receipts have not been filmed or digitized."
                    },
