                ]
              },
              "level" => "collection",
              "originalsloc" => %{
                "head" => "Existence and Location of Originals",
                "id" => "aspace_ac19ff66cc897d23dc5490166b7a3291",
                "p" => "Series 1 through 9 are located at the Caltech Archives. The Director's Files of the Mount Wilson Observatory are located at the Huntington Library."
              },
              "processinfo" => %{
                "head" => "Processing Information",
                "id" => "aspace_2e4194528c8eaf1c669d3da2d21635f6",
                "p" => [
                  "In April 1966, with the Hale family's consent, the personal papers and the Mount Wilson files were organized and catalogued under the direction of Caltech historian Daniel J. Kevles. The project was undertaken with the cooperation and encouragement of Horace Babcock, Director of Mount Wilson; his predecessor, Ira Bowen; Charles Weiner of the American Institute of Physics' Center for History of Physics; Lee DuBridge, President of Caltech; and Fred Shelley of the National Historical Publications Commission. Most of the financial support for the organization of the papers was provided by the Carnegie Institution of Washington and the California Institute of Technology; the Center for History of Physics provided the remainder of the funds from a grant made to it by the National Science Foundation to facilitate and encourage the preservation of manuscripts in the history of science.",
                  %{
                    "content" => ["The original description of the collection was produced by Kevles and published in the",
                     "in 1968. This description was revised by Charlotte E. Erwin in February 2000 and again by Peter Sachs Collopy in June 2018 to produce the present finding aid."],
                    "title" => "Guide to the Microfilm Edition of the George Ellery Hale Papers"
                  }
                ]
              },
              "relatedmaterial" => %{
                "head" => "Related Materials",
                "id" => "aspace_a496179267c253923a883f4949e21308",
                "p" => "Other manuscript collections which contain material relevant to Hale's life include the records of the National Academy of Sciences National Research Council at the Academy's headquarters in Washington, D.C.; the John C. Merriam Papers at the Library of Congress; the Harry M. Goodwin Papers at the Huntington Library; and the Robert A. Millikan Papers and Helen Wright Collection at the California Institute of Technology."
              },
              "scopecontent" => %{
                "head" => "Scope and Contents",
                "id" => "aspace_0b130e5f4c18f3ad41f4c84b1f22ec9b",
                "p" => "This collection provides a thorough record of George Ellery Hale's activities. A prolific correspondent, Hale kept copies of most of his letters. The collections contains significant material relating to the theoretical and instrumental development of astrophysics, the history of the Mount Wilson and Palomar Observatories, and the early history of the California Institute of Technology. It also documents Hale's work with the National Academy of Sciences and National Research Council."
              },
              "userestrict" => %{
                "head" => "Conditions Governing Use",
                "id" => "aspace_01115313af0f156a3661d68ccc7a22bc",
                "p" => ["Because George Ellery Hale died over 70 years ago, his unpublished works are in the public domain and may be reproduced freely. Copyright to works by others, and to Hale's publications, may be held by their respective creators, those creators' heirs, or their publishers. If you wish to quote or reproduce such works beyond the extent of fair use, please contact the copyright holder to request permission.",
                 "(\"Fair use\" is a legal principle which permits unlicensed reproduction in certain circumstances. You are responsible for determining whether your own reproduction would fit the legal requirements for fair use.)"]
              }
            },
